package com.cni.ingestion; import com.cni.casefile.CaseRepository; import com.cni.casefile.CaseAccessService;
import com.cni.audit.AuditService; import com.cni.user.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.security.MessageDigest; import java.time.Instant; import java.util.*;
@RestController @Transactional @RequestMapping("/api/v1/ingestion") @RequiredArgsConstructor public class IngestionController{private final IngestionRepository repo;private final CaseRepository cases;private final CaseAccessService access;private final UserRepository users;private final AuditService audit;@Value("${app.storage.path:./data/uploads}")private String storage;@GetMapping public List<Map<String,Object>> list(@RequestParam UUID caseId,Authentication a){access.require(caseId,a);return repo.findByInvestigationCase_IdOrderByCreatedAtDesc(caseId).stream().map(this::view).toList();}@PostMapping(consumes="multipart/form-data")public Map<String,Object> upload(@RequestParam UUID caseId,@RequestParam String sourceType,@RequestParam(required=false) MultipartFile file,@RequestParam(required=false) String notes,Authentication a)throws Exception{var c=access.require(caseId,a);var u=users.findByUsername(a.getName()).orElseThrow();String name=file==null?"Manual entry":Objects.requireNonNullElse(file.getOriginalFilename(),"uploaded");String stored=null,sha=null,ctype=null;long size=0;long records=0;if(file!=null&&!file.isEmpty()){var dir=Paths.get(storage).toAbsolutePath().normalize();Files.createDirectories(dir);stored=UUID.randomUUID()+"-"+Paths.get(name).getFileName();var target=dir.resolve(stored);file.transferTo(target);var digest=MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(target));sha=HexFormat.of().formatHex(digest);ctype=file.getContentType();size=file.getSize();records=Math.max(1,size/80);}var x=repo.save(DataIngestion.builder().investigationCase(c).createdBy(u).sourceType(sourceType).fileName(name).recordCount(records).status("REVIEW_REQUIRED").notes(notes).storedName(stored).sha256(sha).contentType(ctype).sizeBytes(size).createdAt(Instant.now()).build());return view(x);}@PostMapping("/manual")public Map<String,Object> manual(@RequestBody Req r,Authentication a){var c=access.require(r.caseId(),a);var u=users.findByUsername(a.getName()).orElseThrow();var x=repo.save(DataIngestion.builder().investigationCase(c).createdBy(u).sourceType(r.sourceType()).fileName("Manual entry").recordCount(r.recordCount()).status("REVIEW_REQUIRED").notes(r.notes()).createdAt(Instant.now()).build());return view(x);}@PostMapping("/{id}/approve")public Map<String,Object> approve(@PathVariable UUID id,Authentication a){var x=repo.findById(id).orElseThrow();access.require(x.getInvestigationCase().getId(),a);x.setStatus("IMPORTED");audit.log(a,"INGESTION_APPROVED","INGESTION",id,x.getFileName());return view(repo.save(x));}private Map<String,Object> view(DataIngestion x){Map<String,Object> m=new LinkedHashMap<>();m.put("id",x.getId());m.put("caseId",x.getInvestigationCase().getId());m.put("sourceType",x.getSourceType());m.put("fileName",x.getFileName());m.put("recordCount",x.getRecordCount());m.put("status",x.getStatus());m.put("notes",Objects.toString(x.getNotes(),""));m.put("sha256",x.getSha256());m.put("contentType",x.getContentType());m.put("sizeBytes",x.getSizeBytes());m.put("createdAt",x.getCreatedAt());return m;}public record Req(UUID caseId,String sourceType,long recordCount,String notes){} }
